head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS30200.xml';
scwin.vCreditValuTpCd = 1;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.vCreditValuInstNm = '', scwin.vSameGrdYn = '';
scwin.vCheck_RcvYn = '';
scwin.vProcStdCdCnt = 0, scwin.vAcptDataCnt = 0;
scwin.vDuplStdCdCnt = 0;
scwin.vEtcChgStdCdCnt = 0;
scwin.btnStat = new Object();
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명  	 : fn_Search
 * 설명       : 신용평가 수신정보를 조회 한다.
 ***********************************************/
scwin.fn_Search = function() {
    var dsNm = 'BNS_CLS_CREDIT_INFO';
    var qryId = 'lds.stf.bnscls.select.readCreditValuInstRcv';
    var param = '&{P}V_RCV_DD=' + $c.stf.getObjectValue(edt_RcvDd);
    param += '&{P}V_CREDIT_PROCS_TP_CD=' + scwin.vCreditValuTpCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};

/********************************************** 
 * 함수명  	 : fn_SetBtnProcStat
 * 설명       : 처리완료 버튼 활성/비활성 설정
 ***********************************************/
scwin.fn_SetBtnProcStat = function(vStrtDd) {
    if (vStrtDd != '') {
        //처리완료시
        btn_Proc.src = '../img/bns/btn_20_d.gif';
        scwin.btnStat.Proc = 'dis';
    } else {
        if ($c.stf.getObjectValue(edt_RcvDd) == scwin.vCurDate) {
            btn_Proc.src = '../img/bns/btn_20.gif';
            scwin.btnStat.Proc = 'en';
            //채권매매달력에서 적용일을 구함
            $c.stf.setObjectValue(edt_StrtDd, dts_DtlInfo.getCellData(1, "CLS_STRT_DD"));
        } else {
            btn_Proc.src = '../img/bns/btn_20_d.gif';
            scwin.btnStat.Proc = 'dis';
            $c.stf.setObjectValue(edt_StrtDd, '');
        }
    }
};



/********************************************** 
 * 함수명  	 : fn_srt_list_sync
 * 설명       : 평가사 수신 요약정보 내역을 조회 한다.
 ***********************************************/
scwin.fn_srt_list_sync = function() {
    var dsNm = 'BNS_CLS_CREDIT_SRT_INFO';
    var qryId = 'lds.stf.bnscls.select.listCreditValuInstRcvSrt';
    var param = '&{P}V_RCV_DD=' + $c.stf.getObjectValue(edt_RcvDd);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SrtInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 신용평가 수신정보 내역을 조회 한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNS_CLS_CREDIT_LIST';
    var qryId = 'lds.stf.bnscls.select.listCreditValuRcv';
    var param = '&{P}V_RCV_DD=' + $c.stf.getObjectValue(edt_RcvDd);
    param += '&{P}V_RCV_DD_END=' + '';
    param += '&{P}V_CREDIT_VALU_INST_NM=' + scwin.vCreditValuInstNm;
    param += '&{P}V_SAME_GRD_YN=' + scwin.vSameGrdYn;
    param += '&{P}V_STD_CD=' + ''; //신용평가 수신내역 기록 팝업 조회용도
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};

/********************************************** 
 * 함수명  	 : fn_SetBgColor_list
 * 설명       : 수신내역 목록의 배경색 설정
 ***********************************************/
scwin.fn_SetBgColor_list = function() {
    //그리드 컬럼 ID 구하기
    var arrColID = [];
    for (var i = 0; i < grd_List.getTotalCol(); i++) {
        arrColID.push(grd_List.getColumnID(i));
    }

    //평가등급 일치여부가 N인 로우의 배경색 Light Yellow로 설정
    for (var j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_List, arrColID[j], 'BgColor', "{decode(SAME_GRD_YN,'N','#FFFF99','Y','#FFFFFF',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};



/********************************************** 
 * 함수명  	 : fn_get_rcv_yn
 * 설명       : 신용평가사로부터 수신완료 여부 확인
 ***********************************************/
scwin.fn_get_rcv_yn = function() {
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnscls.select.readCreditValuInstRcvYn';
    var param = '&{P}V_RCV_DD=' + $c.stf.getObjectValue(edt_RcvDd);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_RcvYn, dsNm, qryId, param);
};

/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    // 수신완료 체크 : 4개 평가사로부터 모두 수신완료 되어야 한다. 2024.04.22 김효준 추가
    if (scwin.vCheck_RcvYn == 'N') {
        $c.win.alert("모든 평가사로부터 수신이 완료되지 않았습니다.");
        return false;
    }
    if ($c.stf.getObjectValue(edt_StrtDd) == '') {
        $c.win.alert("[적용일]을 입력하십시오.");
        return false;
    }
    if (scwin.fn_GetDupStdCd() != '') {
        $c.win.alert('[' + scwin.fn_GetDupStdCd() + '] 중복된 종목이 존재합니다.\n\n 해당 종목의 [한글종목명]을 클릭하여 수신내역을 확인하시기 바랍니다.');
        return false;
    }
    if (scwin.vEtcChgStdCdCnt > 0) {
        $c.win.alert('금일 수신된 종목중 기타변경 처리완료건이 존재합니다.\n\n동일 종목의 신용등급변경과 기타변경은 중복조치가 불가하니\n\n해당 종목의 처리내용을 확인하시기 바랍니다.');
        return false;
    }

    //처리완료시 수신내역 유효성체크 (fn_list_sync() 수신내역조회 쿼리에서 이미 유효성체크 결과를 가지고있음)
    if (scwin.fn_check_res_data() != 'Y') {
        $c.win.alert('금일 수신된 종목중 유효하지 않은 등급이 존재합니다.\n\n수신된 신용평가 등급을 확인하시기 바랍니다.\n\n시스템담당자에게 연락하시기 바랍니다.');
        return false;
    }
};



/********************************************** 
 * 함수명  	 : fn_etc_chg_std_cd
 * 설명       : 기타변경 처리종목
 ***********************************************/
scwin.fn_etc_chg_std_cd = function() {
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnscls.select.listWithEtcChgStdCd';
    var param = '&{P}V_START_DD=' + $c.stf.getObjectValue(edt_StrtDd);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_EtcChgStdCd, dsNm, qryId, param);
    dts_EtcChgStdCd.SyncLoad = "true";
};


/********************************************** 
 * 함수명  	 : fn_dupl_std_cd
 * 설명       : 수신평가등급을 중복체크
 ***********************************************/
scwin.fn_dupl_std_cd = function() {
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnscls.select.listWithDuplStdCd';
    var param = '';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DuplStdCd, dsNm, qryId, param);
    dts_DuplStdCd.SyncLoad = "true";
};


/********************************************** 
 * 함수명  	 : fn_list_std_cd
 * 설명       : 수신평가등급을 처리완료하기 위한 종목 내역 조회
 ***********************************************/
scwin.fn_list_std_cd = function() {
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnscls.select.listWithProcsStdCd';
    var param = '';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ProcStdCd, dsNm, qryId, param);
    dts_ProcStdCd.SyncLoad = "true";
};

/********************************************** 
 * 함수명  	 : fn_ProcsComplt
 * 설명       : 처리완료 진행
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return;
    var output = '',
        vStdCd = '';
    if (scwin.vProcStdCdCnt == 0) {
        output = "평가등급이 변경된 종목이 없습니다." + "\n\n";
    } else {
        vStdCd = 'EXIST';
        //vStdCd = fn_GetStdCd();

    }
    output += "처리결과 종목은 처리완료내역 탭에서 조회가 가능합니다.";
    output += "\n" + "[신용등급수신] 처리 하시겠습니까?";
    if (!confirm(output)) return;
    var url = "/bns/CreditValu.do?method=processCreditValuRcvProcessComplt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    url += "&STD_CD=" + vStdCd;

    /**
     * 	- 변경된 데이터가 없더라도 데이터셋 전송하여 접수 진행
     */
    dts_DtlInfo.UseChangeInfo = "False";
    dts_ProcStdCd.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명  	 : fn_GetDupStdCd
 * 설명       : 수신평가등급을 처리완료하기 위한 표준코드 중 중복코드 반환
 ***********************************************/
scwin.fn_GetDupStdCd = function() {
    var returnVal = '';
    for (var i = 1; i <= scwin.vDuplStdCdCnt; i++) {
        returnVal += "'" + dts_DuplStdCd.getCellData(i, "TEXT") + "',";
    }
    return returnVal.substring(0, returnVal.length - 1);
};


/********************************************** 
 * 함수명  	 : fn_GetStdCd
 * 설명       : 수신평가등급을 처리완료하기 위한 표준코드 반환
 ***********************************************/
scwin.fn_GetStdCd = function() {
    var returnVal = '';
    for (var i = 1; i <= scwin.vProcStdCdCnt; i++) {
        returnVal += "'" + dts_ProcStdCd.getCellData(i, "TEXT") + "',";
    }
    return returnVal.substring(0, returnVal.length - 1);
};


/********************************************** 
 * 함수명  	 : fn_check_res_data
 * 설명       : 처리완료시 수신내역 유효성체크
 ***********************************************/
scwin.fn_check_res_data = function() {
    var returnVal = 'Y';
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        //alert(dts_List.NameValue(i, "CHECK_AFCHG_GRD_CNT"));
        if (dts_List.getCellData(i, "CHECK_AFCHG_GRD_CNT") == '0') {
            returnVal = 'N';
            break;
        }
    }
    return returnVal;
};


/********************************************** 
 * 함수명  	 : fn_list_sync_proc
 * 설명       : 신용평가 처리완료내역을 조회 한다.
 ***********************************************/
scwin.fn_list_sync_proc = function() {
    var dsNm = 'BNS_CLS_CREDIT_LIST';
    var qryId = 'lds.stf.bnscls.select.listCreditValuRcvProc';
    var param = '&{P}V_START_DD=' + $c.stf.getObjectValue(edt_StartDd);
    param += '&{P}V_END_DD=' + $c.stf.getObjectValue(edt_EndDd);
    param += '&{P}V_STD_CD=' + $c.stf.getObjectValue(txb_StdCd);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ListProc, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List_Proc);
};


/********************************************** 
 * 함수명   : fn_PassData
 * 설명       : 신용평가 수신내역 기록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_PassData = function(arrPar) {
    var objDtsData = new Object();
    if (scwin.vCreditValuTpCd == 1) {
        objDtsData.STD_CD = dts_List.getCellData(dts_List.getRowPosition(), "STD_CD");
        objDtsData.BND_ISU_NM = dts_List.getCellData(dts_List.getRowPosition(), "BND_ISU_NM");
    } else {
        objDtsData.STD_CD = dts_ListProc.getCellData(dts_ListProc.getRowPosition(), "STD_CD");
        objDtsData.BND_ISU_NM = dts_ListProc.getCellData(dts_ListProc.getRowPosition(), "BND_ISU_NM");
    }
    scwin.arrPar[0] = {
        STD_CD: objDtsData.STD_CD,
        BND_ISU_NM: objDtsData.BND_ISU_NM
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/******************************************************************* 
 * 함수명   : fn_PopCreditValuInstGrd
 * 설명     : 신용평가 수신내역 기록 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopCreditValuInstGrd = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS30201", "/bnscls/ULDBNS30201.gfm", "신용평가 수신내역 기록", obj_left, obj_top, 695, 505, "window");
};


/********************************************** 
 * 함수명   : fn_GetParIsuCd
 * 설명       : 상장채권종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuCd = function(arrPar) {
    scwin.arrPar[0] = {
        LIST_TYPE_CD: '2',
        ISU_NM: $c.stf.getObjectValue(txb_StdCd)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsuCd
 * 설명       : 상장채권종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsuCd = function(arrPar) {
    $c.stf.setObjectValue(txb_StdCd, scwin.arrPar[0].ISU_NM);
};

/********************************************** 
 * 함수명   : fn_ShowIsu
 * 설명       : 상장채권종목 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsu = function(IsuNm) {
    scwin.fn_GetPar = fn_GetParIsuCd;
    scwin.fn_SetPar = fn_SetParIsuCd;
    $c.bns.fn_PopListBndIsuSearch(txb_StdCd);
};


/******************************************************************* 
 * 함수명     : fn_PopCrdtgrdRcvInfo
 * 설명        : 신용등급수신정보조회
 * argument : object
 *******************************************************************/
scwin.fn_PopCrdtgrdRcvInfo = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS30202", "/bnscls/ULDBNS30202.gfm", "신용등급수신정보", obj_left, obj_top, 1030, 500, "window");
};
scwin.gform_onload = function() {
    // 패널라운드 처리(수신내역/처리완료내역)
    $c.bns.BnsPanelToGroupBox(pnl_Recv);
    $c.bns.BnsPanelToGroupBox(pnl_Proc);
    $c.bns.BnsPanelToGroupBox(pnl_Srch);
    $c.bns.BnsPanelToGroupBox(pnl_Srch2);
    $c.stf.showObj(btn_rcvConfrm, false);
    if (js_usr_tp_cd == '1') {
        //운영자이면
        $c.stf.showObj(btn_rcvConfrm, true);
    }
    tab_List.setSelectedTabIndex(1);
    txt_MiRcvInst.setValue('수신평가정보가 없음');

    //수신일 현재일자로 설정
    $c.stf.setObjectValue(edt_RcvDd, scwin.vCurDate);

    //수신일 시작일, 종료일 현재일자로 설정
    $c.stf.setObjectValue(edt_StartDd, scwin.vCurDate);
    $c.stf.setObjectValue(edt_EndDd, scwin.vCurDate);
    scwin.fn_Search();
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vCreditValuTpCd = nIndex;
    if (scwin.vCreditValuTpCd == 2) {
        scwin.fn_list_sync_proc();
    } else {
        scwin.fn_Search();
    }
};
scwin.img_RcvDd_onclick = function() {
    popUpCalendar2(edt_RcvDd);
};
scwin.cmb_CreditValuInstNm_OnSelChange = function() {
    scwin.vCreditValuInstNm = $c.stf.getObjectValue(cmb_CreditValuInstNm);
};
scwin.cmb_SameGrdYn_OnSelChange = function() {
    scwin.vSameGrdYn = $c.stf.getObjectValue(cmb_SameGrdYn);
};
scwin.btn_Srch_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_DtlInfo_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    var vStrtDd = dts_DtlInfo.getCellData(1, "STRT_DD");
    var vMiRcvInst = dts_DtlInfo.getCellData(1, "MI_RCV_INST");
    if (rowcount > 0) {
        txt_MiRcvInst.setValue((vMiRcvInst == '') ? '평가사 수신완료' : '미수신평가사 : ' + vMiRcvInst);
        scwin.fn_SetBtnProcStat(vStrtDd); //처리완료 버튼 활성/비활성 설정

    } else {
        txt_MiRcvInst.setValue('수신평가정보가 없음');
    }
    scwin.fn_list_sync(); //신용평가 수신정보 내역 조회	
    scwin.fn_srt_list_sync(); //신용평가 수신이력 조회

};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, grd_List);
    scwin.fn_SetBgColor_list(); //그리드 배경색 설정

};
scwin.dts_SrtInfo_OnLoadCompleted = function(rowcount) {
    dts_SrtInfo.setRowPosition(0, 0);
};
scwin.dts_RcvYn_OnLoadCompleted = function(rowcount) {
